import itertools, sys, json
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
# generate all valid triples (a,b,c) with a<b and a+b=c
triples = []
for a,b in itertools.combinations(L,2):
    c = a+b
    if c in L and c!=a and c!=b:
        triples.append((a,b,c))
# exact cover backtracking
used = set()
solution = []
nodes_explored = 0

def backtrack(start):
    global nodes_explored, solution
    nodes_explored += 1
    if len(used) == len(L):
        return True
    # select next unused number
    for x in L:
        if x not in used:
            next_num = x
            break
    # try triples containing next_num
    for (a,b,c) in triples:
        if next_num not in (a,b,c):
            continue
        if a in used or b in used or c in used:
            continue
        used.update([a,b,c])
        solution.append((a,b,c))
        if backtrack(start+1):
            return True
        # backtrack
        used.difference_update([a,b,c])
        solution.pop()
    return False
found = backtrack(0)
if found:
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"triples": solution}}
else:
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": True, "nodes_explored": nodes_explored, "method": "backtrack"}
print("WITNESS: " + json.dumps(witness))
